#!/usr/bin/env python3
"""Emit KitchenCore/Resources/foods.json — the bundled food table (ADR-009).

Nutrients are per 100 g edible portion from USDA FoodData Central (SR Legacy
or Foundation Foods; the USDA description is kept so each row can be looked
up). GI values are from the International Tables of Glycemic Index and
Glycemic Load Values (Atkinson, Foster-Powell & Brand-Miller, Diabetes Care
2008; 2021 update). `gi_basis` says whether the value is measured for that
food, a proxy from a close relative, or assumed for a low-carbohydrate food
not in the tables. Edit this file, rerun it, bump VERSION when values change.

Columns: id, name, keywords, usda, carbs, fiber, sodium_mg, sat_fat, gi,
gi_basis, unit_g (one piece), cup_g (one US cup).
"""
import json, sys, pathlib, unicodedata, re

def normalize(text):
    """Mirror of FoodMatcher.normalize: lowercase, accents folded, anything
    but letters, digits and apostrophes becomes a space, whitespace collapsed."""
    folded = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode().lower()
    folded = re.sub(r"\([^)]*\)", " ", folded)
    return " ".join(re.sub(r"[^a-z0-9']+", " ", folded).split())

VERSION = 2
F = []
def food(id, name, kw, usda, carbs, fiber, sodium, satfat, gi, basis, unit=None, cup=None):
    kw = list(dict.fromkeys(normalize(k) for k in kw))
    F.append(dict(id=id, name=name, keywords=kw, usda=usda, carbs=carbs, fiber=fiber, sodium=sodium,
                  satFat=satfat, gi=gi, giBasis=basis, unitGrams=unit, cupGrams=cup))

M, P, A = "measured", "proxy", "assumed"
