ids = [f["id"] for f in F]
assert len(ids) == len(set(ids)), "duplicate ids"
kws = {}
for f in F:
    for k in f["keywords"]:
        assert k == normalize(k) and k, f"keyword not normalized: {k!r}"
        assert k not in kws, f"keyword {k!r} in both {kws[k]} and {f['id']}"
        kws[k] = f["id"]
out = pathlib.Path(__file__).resolve().parent.parent / "KitchenBuddyKit/Sources/KitchenCore/Resources/foods.json"
doc = {
    "version": VERSION,
    "nutrientSource": "USDA FoodData Central (SR Legacy and Foundation Foods), per 100 g edible portion; a few branded averages where USDA has no generic entry",
    "glycemicIndexSource": "Atkinson FS, Foster-Powell K, Brand-Miller JC. International Tables of Glycemic Index and Glycemic Load Values: 2008. Diabetes Care 2008;31(12):2281–2283; and the 2021 update, Am J Clin Nutr 2021;114(5):1625–1632",
    "foods": F,
}
out.write_text(json.dumps(doc, ensure_ascii=False, indent=1, sort_keys=False) + "\n")
print(f"wrote {out} — {len(F)} foods, {len(kws)} keywords")
